"""Exporter un nuage cartesien unique depuis les poses retenues hors ligne."""
from pathlib import Path
import json,csv,math,collections
OUT=Path(__file__).resolve().parent/'resultats'/'fusion_finale'
data=json.loads((OUT/'fusion.json').read_text(encoding='utf-8'));summary=data['summary'];vox={};input_points=0;filtered=0
for scan in data['scans']:
 pose=scan['pose'];a=math.radians(pose['theta']);co,si=math.cos(a),math.sin(a)
 for i,(x,y) in enumerate(scan['points']):
  quality=scan['qualities'][i]
  if not .2<=math.hypot(x,y)<=12 or quality is None or quality<100:filtered+=1;continue
  X=pose['x']+co*x-si*y;Y=pose['y']+si*x+co*y;key=(math.floor(X/.05),math.floor(Y/.05))
  if key not in vox:vox[key]=[0.,0.,0,set()]
  v=vox[key];v[0]+=X;v[1]+=Y;v[2]+=1;v[3].add(scan['index']);input_points+=1
points=[[round(v[0]/v[2],5),round(v[1]/v[2],5),v[2],len(v[3])] for _,v in sorted(vox.items())]
summary.update({'mergedPointCount':len(points),'pointsBeforeVoxelFilter':input_points,'filteredMeasurements':filtered,'voxelSizeM':.05,'displayFilter':'distance 0.20..12 m, intensite >=100, moyenne par voxel de 5 cm','units':'metres'})
with (OUT/'scan_final.csv').open('w',newline='',encoding='utf-8') as f:
 w=csv.writer(f);w.writerow(['x_m','y_m','observations','distinct_scans']);w.writerows(points)
with (OUT/'scan_final.ply').open('w',encoding='ascii') as f:
 f.write(f'ply\nformat ascii 1.0\ncomment Estimated merged lidar cloud, units metres\nelement vertex {len(points)}\nproperty float x\nproperty float y\nproperty float z\nend_header\n')
 for x,y,*_ in points:f.write(f'{x} {y} 0\n')
(OUT/'nuage_fusionne.json').write_text(json.dumps({'summary':summary,'points':points}),encoding='utf-8')
(OUT/'poses_retenues.json').write_text(json.dumps([{'index':s['index']+1,'name':s['name'],'pose':s['pose'],'source':s['poseSource']} for s in data['scans']],indent=2),encoding='utf-8')
metadata=json.dumps({'summary':summary,'points':points},ensure_ascii=False).replace('</','<\\/')
html='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nuage lidar fusionné</title><style>
*{box-sizing:border-box}body{margin:0;background:#0e1c26;color:#edf6f8;font:15px system-ui}header{padding:24px 32px;border-bottom:1px solid #30434e;display:flex;justify-content:space-between;align-items:center;gap:20px}h1{font-size:25px;margin:4px 0}p{color:#9db5c3;font-size:12px;line-height:1.6;margin:5px 0}.tag{font-size:10px;color:#8ae5c9;letter-spacing:2px}button,select{font:inherit;border-radius:8px;padding:9px 13px;border:1px solid #466274;background:#1a3443;color:#eef7fa;cursor:pointer}.tools{display:flex;gap:10px;flex-wrap:wrap;padding:15px 32px;font-size:12px;align-items:center}main{margin:0 25px 15px;background:#f1f5f6;border-radius:12px;overflow:hidden;position:relative;height:calc(100vh - 220px);min-height:450px}canvas{width:100%;height:100%;display:block;cursor:grab;touch-action:none}.caption{padding:0 32px 20px;font-size:12px;color:#a9beca}.pill{padding:8px 12px;border:1px solid #365664;border-radius:7px;color:#b8dbdf;font-size:12px}label{display:flex;align-items:center;gap:8px}@media(max-width:650px){header{padding:20px;display:block}.tools{padding:14px 20px}main{margin:0 12px 12px;height:65vh}.caption{padding:0 20px 20px}h1{font-size:22px}}</style>
<header><div><div class="tag">TP3 · FUSION DES CAPTURES RÉELLES</div><h1>Un seul nuage de points.</h1><p id="summary"></p></div><span class="pill">Recalage estimé · couverture non certifiée</span></header><div class="tools"><button id="fit">Cadrer</button><button id="save">Exporter PNG</button><button id="csv">Télécharger CSV</button><label>Présence minimale <select id="min"><option value="1">1 scan · tous les points retenus</option><option value="2">2 scans</option><option value="3">3 scans · plus stable</option><option value="5">5 scans</option></select></label><span id="count"></span></div><main><canvas id="plot" aria-label="Nuage cartésien fusionné, axes en mètres"></canvas></main><div class="caption">Molette : zoom · glisser : déplacer. Origine : premier scan de la session. Les captures sans recalage suffisamment fiable sont exclues et conservées dans les données sources. Ce résultat est une fusion estimée, pas un tour lidar unique ni une preuve de carte complète.</div>
<script id="data" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent),s=data.summary,c=document.getElementById('plot'),ctx=c.getContext('2d');let view={cx:0,cy:0,scale:30},drag=null;document.getElementById('summary').textContent=`${s.includedCaptures} captures réunies sur ${s.inputCaptures} · ${s.excludedCaptures} sans pose retenue · ${s.mergedPointCount.toLocaleString('fr-FR')} points fusionnés`;
function chosen(){return data.points.filter(p=>p[3]>=Number(document.getElementById('min').value));}
function fit(){const points=chosen();if(!points.length)return;let xmin=Infinity,xmax=-Infinity,ymin=Infinity,ymax=-Infinity;for(const p of points){xmin=Math.min(xmin,p[0]);xmax=Math.max(xmax,p[0]);ymin=Math.min(ymin,p[1]);ymax=Math.max(ymax,p[1]);}const b=c.getBoundingClientRect();view={cx:(xmin+xmax)/2,cy:(ymin+ymax)/2,scale:Math.min((b.width-90)/(xmax-xmin+1),(b.height-80)/(ymax-ymin+1))};draw();}
function draw(){const box=c.getBoundingClientRect(),w=box.width,h=box.height,dpr=window.devicePixelRatio||1;c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#f1f5f6';ctx.fillRect(0,0,w,h);const screen=(x,y)=>[w/2+(x-view.cx)*view.scale,h/2-(y-view.cy)*view.scale],step=view.scale<30?2:1;ctx.strokeStyle='#d4dfe5';ctx.fillStyle='#718997';ctx.lineWidth=1;ctx.font='11px system-ui';for(let x=Math.ceil((view.cx-w/2/view.scale)/step)*step;x<view.cx+w/2/view.scale;x+=step){const p=screen(x,0);ctx.beginPath();ctx.moveTo(p[0],0);ctx.lineTo(p[0],h);ctx.stroke();ctx.fillText(x,p[0]+3,h-10);}for(let y=Math.ceil((view.cy-h/2/view.scale)/step)*step;y<view.cy+h/2/view.scale;y+=step){const p=screen(0,y);ctx.beginPath();ctx.moveTo(0,p[1]);ctx.lineTo(w,p[1]);ctx.stroke();ctx.fillText(y,7,p[1]-3);}const points=chosen();for(const p of points){const q=screen(p[0],p[1]);ctx.fillStyle=p[3]>=5?'#104a59':p[3]>=2?'#187c86':'#61a5aa';ctx.fillRect(q[0]-1,q[1]-1,2.2,2.2);}const origin=screen(0,0);ctx.strokeStyle='#bc6a2d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(origin[0]-6,origin[1]);ctx.lineTo(origin[0]+6,origin[1]);ctx.moveTo(origin[0],origin[1]-6);ctx.lineTo(origin[0],origin[1]+6);ctx.stroke();ctx.fillStyle='#526c7b';ctx.fillText('X →  Y ↑ · mètres',w-140,20);document.getElementById('count').textContent=points.length.toLocaleString('fr-FR')+' points affichés';}
document.getElementById('fit').onclick=fit;document.getElementById('min').onchange=fit;new ResizeObserver(fit).observe(c);c.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,cx:view.cx,cy:view.cy};c.setPointerCapture(e.pointerId);};c.onpointermove=e=>{if(!drag)return;view.cx=drag.cx-(e.clientX-drag.x)/view.scale;view.cy=drag.cy+(e.clientY-drag.y)/view.scale;draw();};c.onpointerup=c.onpointercancel=()=>drag=null;c.addEventListener('wheel',e=>{e.preventDefault();view.scale=Math.max(3,Math.min(600,view.scale*Math.exp(-e.deltaY*.001)));draw();},{passive:false});document.getElementById('save').onclick=()=>{const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download='scan_final.png';a.click();};document.getElementById('csv').onclick=()=>{const text='x_m,y_m,observations,distinct_scans\\n'+chosen().map(p=>p.join(',')).join('\\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='scan_final.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};fit();
</script></html>'''.replace('__DATA__',metadata)
(OUT/'scan_final.html').write_text(html,encoding='utf-8')
print(json.dumps(summary),flush=True)
